-- Cognitive Training: shared training history.
-- Paste into the Supabase dashboard (SQL Editor > New query) and run once.
--
-- Sessions are immutable: the app only inserts and reads them. Each user only ever sees their own rows (RLS).

create table if not exists public.training_sessions (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- SessionRecord.id (a UUID generated by the app); unique per user.
  id text not null,
  started_at timestamptz not null,
  -- Full SessionRecord as stored locally (domain, exercise, levels, breakdown…).
  record jsonb not null,
  created_at timestamptz not null default now(),
  primary key (user_id, id)
);

create index if not exists training_sessions_user_started_idx
  on public.training_sessions (user_id, started_at);

-- Row level security: required on every table exposed through the Data API.
alter table public.training_sessions enable row level security;

drop policy if exists "Users read their own sessions" on public.training_sessions;
create policy "Users read their own sessions"
  on public.training_sessions for select
  to authenticated
  using ((select auth.uid()) = user_id);

drop policy if exists "Users add their own sessions" on public.training_sessions;
create policy "Users add their own sessions"
  on public.training_sessions for insert
  to authenticated
  with check ((select auth.uid()) = user_id);

-- New tables are no longer exposed to the Data API automatically (Supabase change, 2026):
-- grant only what the app needs, to signed-in users only. Nothing for anon.
-- Older projects grant everything by default: reset to the strict minimum.
revoke all on table public.training_sessions from anon, authenticated;
grant select, insert on table public.training_sessions to authenticated;
